def zip_equal\(a, b, fillvalue=None\):
    if len\(a\)!= len\(b\):
        raise UnequalIterablesError\('Input iterables have different lengths'\)
    return zip\(a, b, fillvalue\)

def stagger\(iterable, offsets=(-1, 0, 1), longest=False, fillvalue=None, maxsplit=None\):
    if len\(iterable\) == 0:
        return
    if longest:
        max_offset = max\(offsets\)
        if max_offset < 0:
            raise ValueError\('longest=True requires positive offsets'\)
    try:
        result = list\(itertools.izip_longest\(iterable, *map\(offsets.__getitem__, range\(max_offset + 1\)\)\)
    except TypeError:
        raise ValueError\('iterable must not be empty for longest=True'\)
